            write(K.job, { ...job, phase: 'error', error: 'Phi\u00EAn Gi\u1EDD c\u00F4ng \u0111\u00E3 h\u1EBFt h\u1EA1n; h\u00E3y ch\u1EA1y l\u1EA1i' });
            return;
