            write(K.status, { message: result.warnings.length ? '\u26A0 ' + result.warnings.join(' \u00B7 ') : collected.partial ? '\u2713 \u0110\u00E3 c\u1ED9ng ' + rows.length + '/' + collected.total + ' d\u00F2ng \u0111ang hi\u1EC3n th\u1ECB. Gi\u1EDD c\u00F4ng v\u00E0 DT/Gi\u1EDD ch\u1EC9 ph\u1EA3n \u00E1nh c\u00E1c d\u00F2ng \u0111\u00E3 qu\u00E9t.' : '\u2713 Gi\u1EDD c\u00F4ng & N\u0103ng su\u1EA5t ho\u00E0n t\u1EA5t', at: Date.now(), running: false });
