            write(K.status, { message: result.warnings.length ? '\u26A0 ' + result.warnings.join(' \u00B7 ') : '\u2713 Gi\u1EDD c\u00F4ng v\u00E0 doanh thu nh\u00E2n vi\u00EAn \u0111\u00E3 ho\u00E0n t\u1EA5t', at: Date.now(), running: false });
