/* V88: nhận biết đang chạy (gồm cả Giờ công) */
window.__AutoBIRunning88 = function () {
  try {
    if (GM_getValue('tgdd_auto_state_run_v30', -1) >= 0) return true;
    const job = GM_getValue('autobi_wt73_job', null);
    return !!(job && job.id && !job.cancelled && ['pending', 'collecting', 'core'].includes(job.phase) && Date.now() - (job.at || 0) < 15 * 60000);
  } catch (_) { return false; }
};

/* V86: giữ màn hình sáng suốt lượt chạy trên điện thoại.
   Bản cũ chỉ xin một lần; iPhone tự huỷ khi chuyển trang hoặc khi màn hình ẩn nên máy vẫn tự khoá.
   Bản này xin lại ở mỗi trang, khi trang hiện lại, khi bị huỷ, và dùng video câm siêu nhỏ làm dự phòng. */
(function () {
  'use strict';
  if (window.top !== window.self || window.__AutoBIAwake86) return;
  const running = () => window.__AutoBIRunning88();
  let sentinel = null, video = null, timer = 0, lastNote = '';
  const note = m => { if (m === lastNote) return; lastNote = m; try { window.__AutoBILog5 && window.__AutoBILog5.note(m); } catch (_) { } };
  function startVideo() {
    try {
      if (!video) {
        const canvas = document.createElement('canvas'); canvas.width = canvas.height = 2;
        const ctx = canvas.getContext('2d'); let n = 0;
        timer = setInterval(() => { ctx.fillStyle = (n++ % 2) ? '#010101' : '#020202'; ctx.fillRect(0, 0, 2, 2); }, 1000);
        video = document.createElement('video');
        video.setAttribute('playsinline', ''); video.setAttribute('muted', ''); video.muted = true; video.loop = true; video.autoplay = true;
        video.setAttribute('data-autobi-ui', ''); video.style.cssText = 'position:fixed;left:0;bottom:0;width:1px;height:1px;opacity:0.01;pointer-events:none;z-index:-1';
        if (canvas.captureStream) video.srcObject = canvas.captureStream(1);
        (document.body || document.documentElement).appendChild(video);
      }
      const p = video.play(); if (p && p.catch) p.catch(() => { });
    } catch (_) { }
  }
  function stopVideo() { try { if (video) { video.pause(); video.remove(); } if (timer) clearInterval(timer); } catch (_) { } video = null; timer = 0; }
  async function lock() {
    if (!running() || document.visibilityState !== 'visible') return;
    if (sentinel && !sentinel.released) return;
    if ('wakeLock' in navigator) {
      try {
        sentinel = await navigator.wakeLock.request('screen');
        sentinel.addEventListener('release', () => { sentinel = null; setTimeout(lock, 800); });
        note('Giữ màn hình sáng: đã bật'); stopVideo(); return;
      } catch (e) { note('Giữ màn hình sáng bị trình duyệt từ chối (' + ((e && e.name) || e) + '); dùng cách dự phòng'); }
    } else note('Trình duyệt không hỗ trợ giữ màn hình sáng; dùng cách dự phòng');
    startVideo();
  }
  function release() { try { if (sentinel && !sentinel.released) sentinel.release(); } catch (_) { } sentinel = null; stopVideo(); lastNote = ''; }
  const tick = () => { if (running()) lock(); else release(); };
  document.addEventListener('visibilitychange', () => { if (document.visibilityState === 'visible') tick(); });
  ['pointerdown', 'touchstart', 'click'].forEach(t => document.addEventListener(t, () => { if (running()) lock(); }, { capture: true, passive: true }));
  window.__AutoBIAwake86 = { lock, release, status: () => ({ running: running(), wakeLock: !!(sentinel && !sentinel.released), video: !!video }) };
  setInterval(tick, 3000);
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', tick, { once: true }); else tick();
})();

/* V88: (1) ẩn thanh công cụ dưới khi đang chạy, kể cả Giờ công
        (2) đồng hồ + nút Dừng gọn ở góc dưới bên trái, không che thông báo của BI
        (3) BI báo HTTP 5xx / tải thất bại: tự bấm Tải lại tối đa 3 lần khi trang rảnh */
(function () {
  'use strict';
  if (window.top !== window.self || window.__AutoBIV88) return;
  window.__AutoBIV88 = true;
  try {
    GM_addStyle(`
      html.autobi-running88 #tgdd-bottom-nav { display: none !important; }
      /* V89: đồng hồ + nút Dừng ở góc phải, trên nhãn phiên bản; nhật ký xuống sát đáy khi đang chạy */
      /* V91: một cột ở góc phải — nút Dừng ở trên, đồng hồ ở dưới, cùng kích thước */
      #tgdd-top-right-timer { top: auto !important; left: auto !important; right: 10px !important; bottom: calc(140px + env(safe-area-inset-bottom, 0px)) !important; width: 112px !important; height: 48px !important; box-sizing: border-box !important; display: flex !important; align-items: center !important; justify-content: center !important; font-size: 22px !important; padding: 0 !important; border-width: 2px !important; border-radius: 10px !important; box-shadow: 0 3px 10px rgba(0,0,0,.25) !important; }
      #tgdd-spaceship-wrapper { top: auto !important; left: auto !important; right: 10px !important; bottom: calc(196px + env(safe-area-inset-bottom, 0px)) !important; }
      #tgdd-spaceship-wrapper .autobi-stop85 { width: 112px !important; height: 48px !important; box-sizing: border-box !important; display: flex !important; align-items: center !important; justify-content: center !important; font-size: 20px !important; padding: 0 !important; border: 2px solid rgba(255,255,255,.35) !important; border-radius: 10px !important; }
      html.autobi-running88 #autobi-version-badge { bottom: calc(100px + env(safe-area-inset-bottom, 0px)) !important; }
      html.autobi-running88 #tgdd-run-log-fix5 { bottom: calc(10px + env(safe-area-inset-bottom, 0px)) !important; }
    `);
  } catch (_) { }
  const running = () => window.__AutoBIRunning88();
  const sync = () => { try { document.documentElement.classList.toggle('autobi-running88', running()); } catch (_) { } };
  sync(); setInterval(sync, 500);
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', sync, { once: true });

  const norm = t => String(t || '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/đ/gi, 'd').toLowerCase().replace(/\s+/g, ' ').trim();
  const visible = e => !!e && e.isConnected && e.getClientRects().length > 0 && getComputedStyle(e).visibility !== 'hidden';
  const errorShown = () => [...document.querySelectorAll('[role="alert"],[role="status"],.ant-message-notice,.ant-notification-notice,[class*="toast"],[class*="Toast"],[class*="sonner"],li,div')]
    .some(e => e.children.length < 6 && !e.closest('[data-autobi-ui],[id^="tgdd-"]') && visible(e) && /(http 5\d\d|tai bao cao that bai)/.test(norm(e.textContent)) && norm(e.textContent).length < 160);
  const popupOpen = () => [...document.querySelectorAll('button')].some(b => visible(b) && norm(b.textContent) === 'chon tat ca');
  const reloadButton = () => [...document.querySelectorAll('button')].find(b => visible(b) && !b.disabled && !b.closest('[data-autobi-ui],[id^="tgdd-"]') && ['tai lai', 'xem'].includes(norm(b.textContent)));
  const key = 'autobi_http_retry88:' + location.pathname;
  let since = 0;
  setInterval(() => {
    if (!running()) { since = 0; sessionStorage.removeItem(key); return; }
    if (!errorShown()) { since = 0; return; }
    const G = window.__AutoBILoadingGuard75;
    if ((G && G.loading()) || popupOpen()) { since = 0; return; }
    if (!since) { since = Date.now(); return; }
    if (Date.now() - since < 3000) return;
    since = 0;
    const tries = parseInt(sessionStorage.getItem(key) || '0', 10) || 0;
    if (tries >= 3) return;
    const btn = reloadButton(); if (!btn) return;
    sessionStorage.setItem(key, String(tries + 1));
    try { window.__AutoBILog5 && window.__AutoBILog5.note('BI báo lỗi máy chủ (HTTP 5xx); tự bấm Tải lại lần ' + (tries + 1) + '/3'); } catch (_) { }
    btn.click();
  }, 1000);
})();

